import java.util.*;

class Solution {
    public void flatten(TreeNode root) {
        TreeNode cur = root;
        while (cur != null) {
            if (cur.left != null) {
                TreeNode p = cur.left;
                while (p.right != null) p = p.right;  // last pre-order node of left subtree
                p.right = cur.right;                   // hang old right subtree there
                cur.right = cur.left;
                cur.left = null;
            }
            cur = cur.right;
        }
    }
}

